diff --git a/ta4j-core/src/main/java/org/ta4j/core/rules/AbstractRule.java b/ta4j-core/src/main/java/org/ta4j/core/rules/AbstractRule.java
index eba5e3efe..9efec0fc1 100644
--- a/ta4j-core/src/main/java/org/ta4j/core/rules/AbstractRule.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/rules/AbstractRule.java
@@ -5,0 +6,3 @@ package org.ta4j.core.rules;
+import java.util.LinkedHashMap;
+import java.util.Map;
+
@@ -7,0 +11 @@ import org.slf4j.LoggerFactory;
