diff --git a/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceContext.java b/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceContext.java
new file mode 100644
index 000000000..c7b0cc107
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceContext.java
@@ -0,0 +1,105 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.rules;
+
+import java.util.ArrayDeque;
+import java.util.Deque;
+import java.util.Objects;
+import java.util.function.BooleanSupplier;
+
+import org.ta4j.core.Rule;
+
+/**
+ * Evaluation-scoped trace policy for rule execution.
+ *
+ * <p>
+ * A trace context is stored in a thread-local stack for the duration of one
+ * rule or strategy evaluation. Composite rules use it to pass trace mode, path,
+ * and depth information to children without mutating shared rule instances.
+ *
+ * @since 0.22.7
+ */
+final class RuleTraceContext {
+
+    private static final ThreadLocal<Deque<Frame>> FRAMES = ThreadLocal.withInitial(ArrayDeque::new);
+
+    private RuleTraceContext() {
+    }
+
+    /**
+     * Runs the supplied evaluation with a root trace frame.
+     *
+     * @param traceMode      the trace mode to apply to the evaluation
+     * @param path           root path label
+     * @param parentRuleName optional parent name, such as a strategy name
+     * @param supplier       evaluation callback
+     * @return the callback result
+     * @since 0.22.7
+     */
+    static boolean evaluate(Rule.TraceMode traceMode, String path, String parentRuleName, BooleanSupplier supplier) {
+        Objects.requireNonNull(supplier, "supplier");
+        push(new Frame(normalize(traceMode), normalizePath(path), 0, parentRuleName));
+        try {
+            return supplier.getAsBoolean();
+        } finally {
+            pop();
+        }
+    }
+
+    static Rule.TraceMode activeMode() {
+        Frame frame = currentFrame();
+        if (frame != null) {
+            return frame.traceMode();
+        }
+        return Rule.TraceMode.VERBOSE;
+    }
+
+    static Frame currentFrame() {
+        return FRAMES.get().peek();
+    }
+
+    static Scope openChild(String parentRuleName, String relation) {
+        Frame currentFrame = currentFrame();
+        Rule.TraceMode parentMode = activeMode();
+        Rule.TraceMode childMode = parentMode == Rule.TraceMode.VERBOSE ? Rule.TraceMode.VERBOSE : null;
+        int childDepth = currentFrame == null ? 1 : currentFrame.depth() + 1;
+        String parentPath = currentFrame == null ? "root" : currentFrame.path();
+        String childPath = parentPath + "." + normalizePath(relation);
+
+        push(new Frame(childMode, childPath, childDepth, parentRuleName));
+        return RuleTraceContext::pop;
+    }
+
+    private static void push(Frame frame) {
+        FRAMES.get().push(frame);
+    }
+
+    private static void pop() {
+        Deque<Frame> frames = FRAMES.get();
+        frames.pop();
+        if (frames.isEmpty()) {
+            FRAMES.remove();
+        }
+    }
+
+    private static Rule.TraceMode normalize(Rule.TraceMode traceMode) {
+        return traceMode == null ? Rule.TraceMode.VERBOSE : traceMode;
+    }
+
+    private static String normalizePath(String path) {
+        if (path == null || path.isBlank()) {
+            return "root";
+        }
+        return path.trim().replace(' ', '_');
+    }
+
+    record Frame(Rule.TraceMode traceMode, String path, int depth, String parentRuleName) {
+    }
+
+    interface Scope extends AutoCloseable {
+
+        @Override
+        void close();
+    }
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceEvent.java b/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceEvent.java
new file mode 100644
index 000000000..eec8c4805
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/rules/RuleTraceEvent.java
@@ -0,0 +1,69 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.rules;
+
+import java.util.Collections;
+import java.util.LinkedHashMap;
+import java.util.Map;
+
+import org.ta4j.core.Rule;
+
+/**
+ * Structured rule trace payload emitted by {@link AbstractRule}.
+ *
+ * @param index          the evaluated bar index
+ * @param ruleType       concrete rule class name
+ * @param ruleName       display name used in logs
+ * @param traceMode      active trace mode for this event
+ * @param satisfied      evaluation result
+ * @param path           evaluation path from the trace root
+ * @param depth          evaluation depth from the trace root
+ * @param parentRuleName optional parent rule or strategy name
+ * @param context        deterministic context fields for state-heavy rules
+ * @since 0.22.7
+ */
+record RuleTraceEvent(int index, String ruleType, String ruleName, Rule.TraceMode traceMode, boolean satisfied,
+        String path, int depth, String parentRuleName, Map<String, String> context) {
+
+    /**
+     * Constructor.
+     *
+     * @since 0.22.7
+     */
+    public RuleTraceEvent {
+        context = context == null || context.isEmpty() ? Map.of()
+                : Collections.unmodifiableMap(new LinkedHashMap<>(context));
+    }
+
+    /**
+     * Formats this structured event for the legacy SLF4J trace sink.
+     *
+     * @return stable log message
+     * @since 0.22.7
+     */
+    public String formatMessage() {
+        StringBuilder builder = new StringBuilder().append(ruleName)
+                .append("#isSatisfied(")
+                .append(index)
+                .append("): ")
+                .append(satisfied)
+                .append(" mode=")
+                .append(traceMode)
+                .append(" ruleType=")
+                .append(ruleType)
+                .append(" path=")
+                .append(path)
+                .append(" depth=")
+                .append(depth);
+
+        if (parentRuleName != null && !parentRuleName.isBlank()) {
+            builder.append(" parent=").append(parentRuleName);
+        }
+        for (Map.Entry<String, String> entry : context.entrySet()) {
+            builder.append(' ').append(entry.getKey()).append('=').append(entry.getValue());
+        }
+
+        return builder.toString();
+    }
+}
